import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {guidanceActions,supplyNeeds,observeServices,clearSight,vendorWaypoint} from '../adventure-guidance.js';
import {RIVALS,claimRival,equipRivalGear,settleRivalLevels,installRivals,rivalEnemy} from '../npc-challenges.js';
import {defaultHero} from '../mako.js';import {World} from '../world.js';import {findPath} from '../navigation.js';
const state=()=>({chapter:7,mode:'field',xp:0,gold:0,scene:1,party:[0],recruited:[0,1],heroes:Array.from({length:7},(_,i)=>defaultHero(i)),cores:['earth'],supports:['focus'],items:{tonic:3,ether:2,revive:1},story:{firstCore:true}});
test('guidance offers affordable exact hero/node destinations without mutation or spending',()=>{const s=state(),before=JSON.stringify(s),a=guidanceActions(s);assert.ok(a.some(a=>a.kind==='growth'&&a.hero===0&&a.node));assert.ok(a.some(a=>a.kind==='growth'&&a.hero===1));assert.equal(JSON.stringify(s),before);s.story.firstCore=false;assert.deepEqual(guidanceActions(s),[]);});
test('a merchant is remembered only within sight and inventory thresholds drive the cue',()=>{const s=state(),scene={key:'test',floor:['.........','..#......','.........']},shop={type:'shop',xy:[4,1]},w={state:s,scene,objects:()=>[shop]};s.x=.5;s.y=1.5;observeServices(w);assert.equal(s.guidance.shops.length,0);s.x=4.5;s.y=2.5;observeServices(w);observeServices(w);assert.equal(s.guidance.shops.length,1);assert.deepEqual(supplyNeeds(s),[]);assert.equal(guidanceActions(s).filter(a=>a.kind==='vendor').length,0);s.items.ether=0;assert.equal(guidanceActions(s).find(a=>a.kind==='vendor').shop.scene,1);assert.equal(clearSight(scene,[.5,1.5],[4,1]),false);});
test('each rival pays out once, keeps story flags unchanged, and advances real XP levels',()=>{for(const r of RIVALS){const s=state();s.chapter=12;s.flags={story:3};s.bosses=[];assert.ok(claimRival(s,r.id));assert.equal(s.xp,r.xp);assert.equal(s.gold,r.gold);assert.ok(s.supports.includes(r.support));const before=JSON.stringify(s);assert.equal(claimRival(s,r.id),false);assert.equal(JSON.stringify(s),before);settleRivalLevels(s);assert.ok(s.heroes[0].level>1);assert.deepEqual(s.flags,{story:3});assert.deepEqual(s.bosses,[]);assert.equal(s.resonance.sources['rival:'+r.id].points,1);}});
test('rival gear equips one companion, replaces bonuses and cannot heal through swapping',()=>{const s=state();s.chapter=12;for(const r of RIVALS)claimRival(s,r.id);const h=s.heroes[0],hp=h.hp,power=h.power;assert.ok(equipRivalGear(s,0,RIVALS[0].gear.id));assert.equal(h.power,power+6);assert.equal(h.hp,hp);assert.equal(equipRivalGear(s,1,RIVALS[0].gear.id),false);assert.ok(equipRivalGear(s,0,RIVALS[1].gear.id));assert.equal(h.power,power+4);assert.ok(equipRivalGear(s,1,RIVALS[0].gear.id));assert.equal(h.hp,hp);s.mode='battle';assert.equal(equipRivalGear(s,0,RIVALS[2].gear.id),false);});
test('all rival NPCs have reachable meeting places and real human combat avatars',()=>{const w=new World(JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))));w.state.chapter=12;w.state.story.firstCore=true;installRivals(w);for(const r of RIVALS){let found=false;for(const scene of w.scenes.values()){if(scene.chapter!==r.chapter)continue;w.state.scene=scene.location;const o=w.objects().find(o=>o.rivalId===r.id);if(o){assert.ok(findPath(scene,scene.arrive,o.xy,1).length);found=true;break;}}assert.ok(found,r.id);assert.equal(rivalEnemy(r).rivalAvatar,r.sprite);}});
test('vendor trails never route through unseen rooms or sealed doors',()=>{const a={location:1,chapter:1,key:'a',objects:[],doors:[{to:'b',xy:[1,1]}]},b={location:2,chapter:1,key:'b',objects:[],doors:[]},s=state(),w={state:s,scene:a,scenes:new Map([[1,a],[2,b]]),data:{scenes:[a,b],campaign:{missions:[]}},bit:()=>false};s.guidance={seenScenes:[1]};assert.equal(vendorWaypoint(w,{scene:2}),null);s.guidance.seenScenes.push(2);assert.equal(vendorWaypoint(w,{scene:2}).object,a.doors[0]);a.doors[0].requires_flags=[[1,1]];assert.equal(vendorWaypoint(w,{scene:2}),null);});
test('accepting and winning NPC sparring uses its own reward path without clearing campaign encounters',()=>{let dialog,battle;const w=new World(JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),{onDialog:d=>dialog=d,onBattle:b=>battle=b});w.state.chapter=2;w.state.scene=214;w.state.mode='field';w.state.story.firstCore=true;w.state.story.weapon=true;installRivals(w);const npc=w.objects().find(o=>o.rivalId==='tamsin');w.interact(npc);assert.ok(dialog.choices[0].label.includes('Accept'));assert.equal(w.state.xp,0);dialog.choices[0].action();assert.equal(battle.object.type,'rival');w.winBattle();assert.equal(w.currentBattle,null);assert.equal(w.state.xp,240);assert.deepEqual(w.state.bosses,[]);assert.deepEqual(w.state.rivals.gear,['kiln-bracer']);const xp=w.state.xp;w.winBattle();assert.equal(w.state.xp,xp);});
test('losing friendly sparring grants no rewards and does not record a campaign defeat',()=>{let d;const w=new World(JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),{onDialog:v=>d=v});w.state.chapter=2;w.state.scene=214;w.state.mode='field';w.state.story.firstCore=true;w.state.story.weapon=true;installRivals(w);const npc=w.objects().find(o=>o.rivalId==='tamsin');w.interact(npc);d.choices[0].action();w.loseBattle();assert.equal(w.state.xp,0);assert.deepEqual(w.state.rivals.won,[]);assert.equal(w.state.story.failures[2],undefined);assert.equal(w.currentBattle,null);});
